/**
 * Markdown content negotiation for AI agents.
 *
 * When a client prefers `text/markdown` over HTML (Accept header), serve the
 * build-time markdown twin (<route>/index.md) from the same URL. Browsers send
 * text/html and are never affected. Runs only on routes listed in
 * dist/_routes.json (generated by tools/generate-markdown.mjs from the sitemap),
 * so static assets never invoke this function.
 */
function prefersMarkdown(accept) {
  if (!accept) return false;
  let md = -1;
  let html = -1;
  for (const part of accept.split(',')) {
    const [type, ...params] = part.trim().split(';');
    const t = type.trim().toLowerCase();
    let q = 1;
    for (const p of params) {
      const m = p.trim().match(/^q=([\d.]+)$/i);
      if (m) q = parseFloat(m[1]);
    }
    if (t === 'text/markdown') md = Math.max(md, q);
    else if (t === 'text/html' || t === 'application/xhtml+xml') html = Math.max(html, q);
  }
  return md > 0 && md >= html;
}

export async function onRequest(context) {
  const { request, env, next } = context;

  if ((request.method === 'GET' || request.method === 'HEAD') && prefersMarkdown(request.headers.get('Accept'))) {
    try {
      const url = new URL(request.url);
      const dir = url.pathname.endsWith('/') ? url.pathname : `${url.pathname}/`;
      const res = await env.ASSETS.fetch(new Request(new URL(`${dir}index.md`, url), { method: 'GET' }));
      if (res.ok && !(res.headers.get('Content-Type') || '').includes('text/html')) {
        return new Response(request.method === 'HEAD' ? null : res.body, {
          status: 200,
          headers: {
            'Content-Type': 'text/markdown; charset=utf-8',
            'Vary': 'Accept',
            // Cloudflare's CDN cache ignores Vary: Accept, so a cached markdown copy would be
            // served to browsers (and vice versa). Never let the CDN store these responses.
            'Cache-Control': 'no-store',
            'Cloudflare-CDN-Cache-Control': 'no-store',
            'Content-Signal': 'ai-train=yes, search=yes, ai-input=yes',
            'X-Content-Type-Options': 'nosniff',
          },
        });
      }
    } catch (_) {
      // fall through to the normal HTML response
    }
  }

  const res = await next();
  const out = new Response(res.body, res);
  out.headers.append('Vary', 'Accept');
  // Same reason as above: with the CDN keyed on URL alone, a cached HTML copy would also
  // swallow every later Accept: text/markdown request. Keep the function in the path.
  out.headers.set('Cloudflare-CDN-Cache-Control', 'no-store');
  return out;
}
